code.formula:
@Command([EditDocument];"1");

@If(Dept = ""; @Return(@Do(@Command([EditGotoField];"Dept") ;@Prompt([Ok];"Missing Value"; "Please select your Department!")));"");
@If(PIC = ""; @Return(@Do(@Command([EditGotoField];"PIC") ;@Prompt([Ok];"Missing Value"; "Please enter the name!")));"");
@If(Position = ""; @Return(@Do(@Command([EditGotoField];"Position") ;@Prompt([Ok];"Missing Value"; "Please enter your position!")));"");
@If(Responsibility = ""; @Return(@Do(@Command([EditGotoField];"Responsibility") ;@Prompt([Ok];"Missing Value"; "Please state the area of responsibility!")));"");
@If(HOD = ""; @Return(@Do(@Command([EditGotoField];"HOD") ;@Prompt([Ok];"Missing Value"; "Please select your HOD!")));"");

@If(PIC_1 = "" & Position_1="" & Responsibility_1=""; @Return(@Do(@Command([EditGotoField];"PIC_1") ;@Prompt([Ok];"Missing Value"; "Please enter the Backup person details!")));"");

FIELD SubmitDate := @Now;
FIELD SubmittedBy := @Name([CN];@UserName);
FIELD CurrentAction := "Submitted";
FIELD RemDate := @Adjust(@Today;0;0;3;0;0;0);

@MailSend(HOD;NULL;NULL;"Backup Staff Database - " + PIC;Body;"Please follow this doclink  ------> ";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

par.button:
ludb 		:= "PHBSVR2/PHB":"empinfo.nsf";
luview 	:= "EmpDetails";
Title		:= "Employee Details";
Prompt	:= "Select an employee";
lucol		:= 7;

AllData	:=@PickList([Custom];ludb;luview;title;prompt;lucol);

empname:=@Word(Alldata;"~";2);
desi			:=@Word(Alldata;"~";6);

FIELD PIC		:=@Trim(empname);
FIELD Position	:=@Trim(desi);

